fun positionBelongsToNode(candidate: Node?, position: Int, file: SourceFile?): Boolean {
    if (candidate!!.pos() > position) {
        goPanic("Expected candidate.pos <= position")
    }
    return position < candidate!!.end() || !isCompletedNode(candidate, file)
}

